import { lookupAddress, type LocationDetails } from "./geocoding";
import { resolveGoogleMapsUrl, roundCoordinate, type ParsedCoords } from "./parse-map-url";

export interface LinkLookupResult {
  coords: ParsedCoords;
  details: LocationDetails;
}

/**
 * The one path for "paste a Google Maps link (or lat, lng)": resolve coordinates, then look up
 * the address (Google through the server, OpenStreetMap as fallback). Returns null when the
 * link has no usable coordinates.
 */
export async function lookupLocationFromLink(
  input: string,
  options: { language?: string; signal?: AbortSignal } = {}
): Promise<LinkLookupResult | null> {
  const raw = await resolveGoogleMapsUrl(input, options.signal);
  if (!raw) return null;
  const coords = { lat: roundCoordinate(raw.lat), lng: roundCoordinate(raw.lng) };
  const details = await lookupAddress(coords.lat, coords.lng, { ...options, preferGoogle: true });
  return { coords, details };
}

const COUNTRY_ALIASES: Record<string, string[]> = {
  UAE: ["ae", "uae", "united arab emirates", "emirates", "الإمارات", "الامارات"],
  Egypt: ["eg", "egypt", "مصر"],
  Oman: ["om", "oman", "عمان", "سلطنة عمان"],
  "Saudi Arabia": ["sa", "saudi arabia", "ksa", "السعودية"],
};

/** Maps a geocoder country (name or ISO code) to one of the dashboard's country values. */
export function matchCountry(details: Pick<LocationDetails, "country" | "countryCode">, values: string[]): string | null {
  const candidates = [details.countryCode, details.country].map((v) => v.trim().toLowerCase()).filter(Boolean);
  for (const value of values) {
    const aliases = COUNTRY_ALIASES[value] ?? [value.toLowerCase()];
    if (candidates.some((c) => aliases.includes(c))) return value;
  }
  return null;
}

function normalizeName(value: string): string {
  return value
    .toLowerCase()
    .normalize("NFKD")
    .replace(/[̀-ͯ]/g, "")
    .replace(/^(al|el)[\s-]+/, "")
    .replace(/\b(city|emirate|governorate|district|area)\b/g, "")
    .replace(/[^\p{L}\p{N}]+/gu, " ")
    .trim();
}

/**
 * Finds the option matching a geocoded name: exact (normalized) first, then whole-word
 * containment in either direction. Avoids loose substring hits like "Al" matching everything.
 */
export function matchOptionByName<T extends { label: string; value: string }>(name: string, options: T[]): T | null {
  const needle = normalizeName(name);
  if (!needle) return null;
  const normalized = options.map((option) => ({ option, label: normalizeName(option.label), value: normalizeName(option.value) }));
  const exact = normalized.find((o) => o.label === needle || o.value === needle);
  if (exact) return exact.option;
  const wordMatch = (haystack: string, word: string) =>
    word.length >= 3 && new RegExp(`(^|\\s)${word.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}(\\s|$)`).test(haystack);
  const partial = normalized.find((o) => wordMatch(o.label, needle) || wordMatch(needle, o.label));
  return partial?.option ?? null;
}
