export interface ParsedCoords {
  lat: number;
  lng: number;
}

const NUM = "(-?\\d{1,3}(?:\\.\\d+)?)";
const SEP = "\\s*(?:,|%2C)\\s*\\+?\\s*";

/**
 * Patterns in priority order. The `!3d…!4d` data block is the exact place pin, so it wins over
 * `@lat,lng`, which is only the viewport centre of the page.
 */
const URL_PATTERNS: Array<{ regex: RegExp; latFirst: boolean }> = [
  { regex: new RegExp(`!3d${NUM}!4d${NUM}`), latFirst: true },
  { regex: new RegExp(`!4d${NUM}!3d${NUM}`), latFirst: false },
  { regex: new RegExp(`[?&](?:q|query|destination|daddr|saddr|ll|sll|center|viewpoint)=(?:loc:)?${NUM}${SEP}${NUM}`), latFirst: true },
  { regex: new RegExp(`/(?:search|place|dir)/${NUM}${SEP}${NUM}`), latFirst: true },
  { regex: new RegExp(`@${NUM}${SEP}${NUM}`), latFirst: true },
  { regex: new RegExp(`!2d${NUM}!3d${NUM}`), latFirst: false },
];

export function isValidLatLng(lat: number, lng: number): boolean {
  return (
    Number.isFinite(lat) &&
    Number.isFinite(lng) &&
    lat >= -90 &&
    lat <= 90 &&
    lng >= -180 &&
    lng <= 180 &&
    !(lat === 0 && lng === 0)
  );
}

/** Coordinates are stored with 6 decimals (~11 cm), everywhere. */
export function roundCoordinate(value: number): number {
  return Math.round(value * 1e6) / 1e6;
}

/** Strict number parsing for a typed coordinate: "25.2abc" is rejected instead of becoming 25.2. */
export function parseCoordinateInput(value: string): number | null {
  const trimmed = value.trim().replace(",", ".");
  if (!/^-?\d+(\.\d+)?$/.test(trimmed)) return null;
  const num = Number(trimmed);
  return Number.isFinite(num) ? num : null;
}

export function toCoordinate(value: unknown): number | null {
  if (value === null || value === undefined || value === "") return null;
  const num = typeof value === "number" ? value : Number(value);
  return Number.isFinite(num) ? num : null;
}

/** Returns valid coordinates from loosely typed API values, treating 0/0 and blanks as "no location". */
export function toLatLng(lat: unknown, lng: unknown): ParsedCoords | null {
  const a = toCoordinate(lat);
  const b = toCoordinate(lng);
  return a !== null && b !== null && isValidLatLng(a, b) ? { lat: a, lng: b } : null;
}

export function buildGoogleMapsUrl(lat: number, lng: number): string {
  return `https://www.google.com/maps/search/?api=1&query=${roundCoordinate(lat)},${roundCoordinate(lng)}`;
}

/** Extracts coordinates from a "lat, lng" string or any Google Maps URL format (without network). */
export function extractCoordinates(input: string): ParsedCoords | null {
  if (!input || typeof input !== "string") return null;
  const trimmed = input.trim();

  const direct = trimmed.match(/^\(?\s*(-?\d{1,2}(?:\.\d+)?)\s*[,\s]\s*(-?\d{1,3}(?:\.\d+)?)\s*\)?$/);
  if (direct) {
    const lat = Number(direct[1]);
    const lng = Number(direct[2]);
    return isValidLatLng(lat, lng) ? { lat, lng } : null;
  }

  let decoded = trimmed;
  try {
    decoded = decodeURIComponent(trimmed.replace(/\+/g, " "));
  } catch {
    decoded = trimmed;
  }

  for (const { regex, latFirst } of URL_PATTERNS) {
    const match = decoded.match(regex) ?? trimmed.match(regex);
    if (!match) continue;
    const lat = Number(latFirst ? match[1] : match[2]);
    const lng = Number(latFirst ? match[2] : match[1]);
    if (isValidLatLng(lat, lng)) return { lat, lng };
  }
  return null;
}

export function isShortMapsUrl(input: string): boolean {
  try {
    const host = new URL(input.trim()).hostname.toLowerCase();
    return host === "goo.gl" || host === "maps.app.goo.gl" || host === "g.co" || host.endsWith(".page.link");
  } catch {
    return false;
  }
}

export function isCoordinateText(input: string): boolean {
  return !/^https?:\/\//i.test(input.trim()) && extractCoordinates(input) !== null;
}

/**
 * Coordinates from a pasted link or "lat, lng" text. Short links (maps.app.goo.gl, goo.gl) are
 * expanded once through the server route; everything else is parsed locally.
 */
export async function resolveGoogleMapsUrl(input: string, signal?: AbortSignal): Promise<ParsedCoords | null> {
  const direct = extractCoordinates(input);
  if (direct) return direct;
  if (!isShortMapsUrl(input)) return null;

  const res = await fetch(`/api/expand-url?shortUrl=${encodeURIComponent(input.trim())}`, { signal });
  if (!res.ok) return null;
  const data = await res.json().catch(() => null);
  return typeof data?.longUrl === "string" ? extractCoordinates(data.longUrl) : null;
}
