"use client";

// TEMPORARY visual check for the map components — delete after review.
import { useState } from "react";
import { LocationPickerField, type LocationChange } from "@/components/shared/maps/LocationPickerField";
import { LocationMapPreview } from "@/components/shared/maps/LocationMapPreview";

export default function MapPreviewTest() {
  const [value, setValue] = useState({ latitude: 25.197197 as number | null, longitude: 55.274376 as number | null, mapLink: "" });
  const [last, setLast] = useState<LocationChange | null>(null);
  return (
    <div className="mx-auto max-w-3xl space-y-6 bg-white p-6 dark:bg-neutral-950">
      <LocationPickerField
        value={value}
        onChange={(c) => {
          setValue({ latitude: c.latitude, longitude: c.longitude, mapLink: c.mapLink });
          setLast(c);
        }}
        required
      />
      <pre id="last-change" className="whitespace-pre-wrap text-xs">{JSON.stringify(last)}</pre>
      <div className="w-80">
        <LocationMapPreview latitude="25.0786" longitude="55.1352" label="Dubai Marina" />
      </div>
    </div>
  );
}
